<?php
require_once __DIR__.'/revisar_permisos.php';
require_once __DIR__.'/carga_interesados_helpers.php';
cengi_require_carga_participantes('inscripciones.php?vista=interesados');
$db=conectar();if(empty($_SESSION['ins_csrf']))$_SESSION['ins_csrf']=bin2hex(random_bytes(32));
$error=(string)($_SESSION['carga_interesados_error']??'');unset($_SESSION['carga_interesados_error']);
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
 if(!hash_equals($_SESSION['ins_csrf'],(string)($_POST['csrf']??'')))throw new InvalidArgumentException('Actualiza la página antes de continuar.');
 $accion=$_POST['accion']??'';
 if($accion==='analizar'){
  unset($_SESSION['ci_borrador']);$filas=cengi_ci_leer($_FILES['archivo']??[]);
  $defectos=['curso'=>($_POST['modo']??'varios')==='unico'?(int)($_POST['curso']??0):0,'pagador'=>trim((string)($_POST['pagador']??'')),'cuota'=>trim((string)($_POST['cuota']??''))];
  if(($_POST['modo']??'')==='unico'&&!$defectos['curso'])throw new InvalidArgumentException('Selecciona el curso común.');
  $_SESSION['ci_borrador']=['filas'=>$filas,'defectos'=>$defectos,'analisis'=>cengi_ci_analizar($db,$filas,$defectos),'token'=>bin2hex(random_bytes(24)),'creado'=>time(),'archivo'=>basename($_FILES['archivo']['name'])];
  header('Location: carga_interesados.php?revisar=1');exit;
 }elseif($accion==='confirmar'){
  $b=$_SESSION['ci_borrador']??null;if(!$b||time()-$b['creado']>1800||!hash_equals($b['token'],(string)($_POST['token']??'')))throw new InvalidArgumentException('La revisión venció o ya fue procesada. Vuelve a analizar el archivo.');
  $_SESSION['ci_resultado']=cengi_ci_importar($db,$b['filas'],$b['defectos']);unset($_SESSION['ci_borrador']);header('Location: carga_interesados.php?resultado=1');exit;
 }elseif($accion==='descartar'){unset($_SESSION['ci_borrador']);header('Location: carga_interesados.php');exit;}
 else throw new InvalidArgumentException('Acción no válida.');
}catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'No fue posible completar la carga. Intenta nuevamente.';if(!($e instanceof InvalidArgumentException))error_log('Carga flexible de interesados: '.$e->getMessage());}
$borrador=$_SESSION['ci_borrador']??null;if($borrador&&time()-$borrador['creado']>1800){unset($_SESSION['ci_borrador']);$borrador=null;}
$resultado=$_SESSION['ci_resultado']??null;unset($_SESSION['ci_resultado']);
$cursos=$db->query('SELECT id,nombre_cursos,codigo_curso,inicio FROM cursos ORDER BY inicio DESC,nombre_cursos,id')->fetchAll(PDO::FETCH_ASSOC);
$seleccion=(int)($_GET['curso']??($borrador['defectos']['curso']??($_POST['curso']??0)));
$modo=$_POST['modo']??($seleccion?'unico':'varios');
$cuota=$_POST['cuota']??($borrador['defectos']['cuota']??'');$pagador=$_POST['pagador']??($borrador['defectos']['pagador']??'');
$detalle=$borrador['analisis']??($resultado['detalle']??[]);$cuentas=['lista'=>0,'error'=>0,'omitida'=>0];foreach($detalle as $r)$cuentas[$r['estado']]++;
require_once __DIR__.'/menu.php';require_once __DIR__.'/administracion_nav.php';
?>
<!DOCTYPE html><html lang="es"><head><?php cengi_pp_head('Carga flexible de interesados'); ?>
<link rel="stylesheet" href="css/necesidades_capacitacion.css?v=<?=filemtime(__DIR__.'/css/necesidades_capacitacion.css')?>"><link rel="stylesheet" href="css/carga_interesados.css?v=<?=filemtime(__DIR__.'/css/carga_interesados.css')?>"></head>
<body class="cengi-canvas cg-tema"><?php menu_render(); ?><main class="nc-report ci-page">
<header class="nc-hero"><small>CAPACITACIÓN · INSCRIPCIONES</small><h1>Carga masiva de interesados</h1><p>Un archivo, distintos cursos y pagadores. Revisa los datos antes de registrarlos.</p><div class="ci-steps"><span class="<?=!$borrador&&!$resultado?'is-current':''?>">1 · Preparar archivo</span><span class="<?=$borrador?'is-current':''?>">2 · Revisar registros</span><span class="<?=$resultado?'is-current':''?>">3 · Confirmar carga</span></div></header>
<?php cengi_ins_nav('interesados');cengi_pp_feedback($error,'error'); ?>
<?php if($resultado):?><section class="ci-result" role="status"><strong>Carga completada: <?=(int)$resultado['procesados']?> registros en <?=(int)$resultado['cursos']?> cursos</strong><p><?=(int)$resultado['omitidos']?> filas omitidas. Consulta el detalle abajo; las inscripciones nuevas continúan con su validación habitual.</p><a class="btn btn-success" href="inscripciones.php?vista=interesados">Ver Interesados</a></section><?php endif;?>
<?php if(!$borrador):?><div class="ci-layout"><section class="nc-panel ci-main"><div class="ci-section-title"><span>01</span><div><h2>Prepara la carga</h2><p>Los datos de cada fila tienen prioridad sobre los valores comunes.</p></div></div>
<form action="carga_interesados.php" method="post" enctype="multipart/form-data" id="ci-form"><input type="hidden" name="csrf" value="<?=cengi_pp_h($_SESSION['ins_csrf'])?>"><input type="hidden" name="accion" value="analizar">
<fieldset class="ci-mode"><legend>¿Qué vas a cargar?</legend><label><input type="radio" name="modo" value="varios" <?=$modo==='varios'?'checked':''?>> <span><b>Varios cursos</b><small>Indica el curso de cada participante en el archivo.</small></span></label><label><input type="radio" name="modo" value="unico" <?=$modo==='unico'?'checked':''?>> <span><b>Un solo curso</b><small>Usa un curso común y combina pagadores y cuotas.</small></span></label></fieldset>
<label class="ci-wide" id="ci-course-wrap">Curso común<select name="curso" id="ci-course" class="form-control"><option value="">Selecciona un curso</option><?php foreach($cursos as $c):?><option value="<?=(int)$c['id']?>" <?=$seleccion===(int)$c['id']?'selected':''?>><?=cengi_pp_h($c['nombre_cursos'].' · '.($c['inicio']?:'Sin fecha').' · ID '.$c['id'])?></option><?php endforeach;?></select></label>
<div class="ci-defaults ci-wide"><div><h3>Valores comunes <small>opcionales</small></h3><p>Solo se aplican cuando la celda correspondiente está vacía.</p></div><div class="ci-two"><label>Quién paga<select name="pagador" class="form-control"><option value="">Leer de cada fila</option><?php foreach(['Propio'=>'Pago propio','Ingenio'=>'Ingenio / institución'] as $k=>$v):?><option value="<?=$k?>" <?=$pagador===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Tipo de cuota<select name="cuota" class="form-control"><option value="">Leer de cada fila</option><?php foreach(CENGI_INS_CUOTAS as $k=>$v):?><option value="<?=$k?>" <?=$cuota===$k?'selected':''?>><?=cengi_pp_h($v[0])?></option><?php endforeach;?></select></label></div></div>
<label class="ci-upload ci-wide" for="ci-file"><span class="glyphicon glyphicon-cloud-upload" aria-hidden="true"></span><strong>Selecciona tu archivo de interesados</strong><span>Excel XLSX / XLS o CSV · hasta 500 filas · máximo 5 MB</span><input id="ci-file" type="file" name="archivo" accept=".xlsx,.xls,.csv" required><small id="ci-file-name">Todavía no has seleccionado un archivo.</small></label>
<div class="ci-buttons ci-wide"><button class="btn btn-success" type="submit"><span class="glyphicon glyphicon-search"></span> Analizar y revisar</button><a class="btn btn-default" href="inscripciones.php?vista=interesados">Volver a Interesados</a></div><p class="ci-safe ci-wide">Analizar el archivo no guarda inscripciones. Confirmarás los registros después de revisarlos.</p></form></section>
<aside class="nc-panel ci-guide"><div class="ci-section-title"><span>↓</span><div><h2>Plantillas actualizadas</h2><p>Curso, pagador y cuota por participante.</p></div></div><a class="btn nc-export" href="plantilla_interesados.php">Descargar Excel</a><a class="btn btn-default" href="plantilla_interesados.php?formato=csv">Descargar CSV</a><h3>Columnas flexibles</h3><dl><dt>ID_CURSO o CURSO</dt><dd>Usa el ID, código o nombre exacto. Repite a una persona en otra fila si participa en otro curso.</dd><dt>QUIEN_PAGA</dt><dd>Propio o Ingenio.</dd><dt>TIPO_CUOTA</dt><dd>Asociado, Externo o Extranjero.</dd></dl><p>La plantilla Excel incluye una hoja con los cursos y sus identificadores.</p><details><summary>Datos del participante</summary><p>INGENIO, CUI, NOMBRE, PUESTO, AREA, CORREO_ELECTRONICO, GRADO_ACADEMICO y TELEFONO.</p><p>El CUI es opcional. Conserva CUI y teléfono como texto. El ingenio debe estar registrado en el sistema.</p></details></aside></div><?php endif;?>
<?php if($borrador||$resultado):?><section class="nc-panel ci-preview"><div class="ci-section-title"><span>02</span><div><h2><?=$borrador?'Revisa antes de registrar':'Detalle de la carga'?></h2><p><?=$borrador?cengi_pp_h($borrador['archivo']):'Resultados por fila'?></p></div></div>
<div class="ci-counters"><div><b><?=count($detalle)?></b><span>Filas analizadas</span></div><div class="is-green"><b><?=$cuentas['lista']?></b><span><?=$resultado?'Registradas':'Listas para cargar'?></span></div><div class="is-orange"><b><?=$cuentas['error']?></b><span>Con errores</span></div><div><b><?=$cuentas['omitida']?></b><span>Se omiten</span></div></div>
<div class="ci-preview-tools"><label>Buscar en el archivo<input class="form-control" id="ci-preview-search" type="search" placeholder="Nombre, curso, correo o ingenio"></label><label>Mostrar<select id="ci-preview-state" class="form-control"><option value="">Todas las filas</option><option value="lista"><?=$resultado?'Registradas':'Listas'?></option><option value="error">Con errores</option><option value="omitida">Omitidas</option></select></label></div>
<div class="ci-table-wrap"><table class="table"><thead><tr><th>Fila</th><th>Participante</th><th>Curso / diplomado</th><th>Quién paga</th><th>Tipo de cuota</th><th>Revisión</th></tr></thead><tbody id="ci-preview-rows"><?php foreach($detalle as $r):?><tr data-state="<?=$r['estado']?>"><td><?=(int)$r['linea']?></td><td><strong><?=cengi_pp_h($r['datos']['nombre']??'Sin nombre')?></strong><small><?=cengi_pp_h($r['datos']['correo']??'')?> · <?=cengi_pp_h($r['datos']['ingenio']??'')?></small></td><td><?=cengi_pp_h($r['curso_nombre']?:($r['datos']['curso']??'Sin curso'))?><small><?=$r['curso_id']?'ID '.(int)$r['curso_id']:''?></small></td><td><?=cengi_pp_h($r['pagador']??($r['datos']['pagador']??'—'))?></td><td><?=cengi_pp_h(ucfirst($r['cuota']??($r['datos']['cuota']??'—')))?></td><td><span class="ci-badge is-<?=$r['estado']?>"><?=cengi_pp_h($r['estado']==='lista'&&$resultado?'Registrada':$r['detalle'])?></span></td></tr><?php endforeach;?></tbody></table></div>
<?php if($borrador):?><div class="ci-confirm"><p>Se registrarán únicamente las <b><?=$cuentas['lista']?> filas válidas</b>. Los datos se vuelven a comprobar al confirmar. Los registros existentes se conservan.</p><div class="ci-buttons"><form method="post"><input type="hidden" name="csrf" value="<?=cengi_pp_h($_SESSION['ins_csrf'])?>"><input type="hidden" name="accion" value="confirmar"><input type="hidden" name="token" value="<?=cengi_pp_h($borrador['token'])?>"><button class="btn btn-success" <?=$cuentas['lista']?'':'disabled'?>>Registrar <?=$cuentas['lista']?> interesados</button></form><form method="post"><input type="hidden" name="csrf" value="<?=cengi_pp_h($_SESSION['ins_csrf'])?>"><input type="hidden" name="accion" value="descartar"><button class="btn btn-default" type="submit">Cambiar archivo o valores comunes</button></form></div></div><?php endif;?></section><?php endif;?>
<p class="ci-footer-note">El pago propio continúa con la revisión de la boleta por Administración; el pago del ingenio, con su autorización y seguimiento por proforma. La carga no confirma pagos ni modifica asignaciones académicas existentes. Los cursos gratuitos conservan su flujo habitual.</p>
